1	import { create } from "@bufbuild/protobuf";
2	import { FieldMaskSchema } from "@bufbuild/protobuf/wkt";
3	import type { InfiniteData } from "@tanstack/react-query";
4	import { useInfiniteQuery, useMutation, useQuery, useQueryClient } from "@tanstack/react-query";
5	import { memoServiceClient } from "@/connect";
6	import { userKeys } from "@/hooks/useUserQueries";
7	import { DEFAULT_LIST_MEMOS_PAGE_SIZE } from "@/lib/constants";
8	import type { ListMemosRequest, ListMemosResponse, Memo } from "@/types/proto/api/v1/memo_service_pb";
9	import { ListMemoCommentsRequestSchema, ListMemosRequestSchema, MemoSchema } from "@/types/proto/api/v1/memo_service_pb";
10	
11	// Query keys factory for consistent cache management
12	export const memoKeys = {
13	  all: ["memos"] as const,
14	  lists: () => [...memoKeys.all, "list"] as const,
15	  list: (filters: Partial<ListMemosRequest>) => [...memoKeys.lists(), filters] as const,
16	  details: () => [...memoKeys.all, "detail"] as const,
17	  detail: (name: string) => [...memoKeys.details(), name] as const,
18	  comments: (name: string) => [...memoKeys.all, "comments", name] as const,
19	  linkMetadata: (url: string) => [...memoKeys.all, "linkMetadata", url] as const,
20	};
21	
22	type MemoPatch = Partial<Memo> & Pick<Memo, "name">;
23	type MemoCollectionQueryData = ListMemosResponse | InfiniteData<ListMemosResponse>;
24	
25	function isMemoListResponse(data: unknown): data is ListMemosResponse {
26	  return typeof data === "object" && data !== null && Array.isArray((data as { memos?: unknown }).memos);
27	}
28	
29	function isInfiniteMemoListData(data: unknown): data is InfiniteData<ListMemosResponse> {
30	  return typeof data === "object" && data !== null && Array.isArray((data as { pages?: unknown }).pages);
31	}
32	
33	function patchMemoListResponse(response: ListMemosResponse, update: MemoPatch): ListMemosResponse {
34	  let changed = false;
35	  const memos = response.memos.map((memo) => {
36	    if (memo.name !== update.name) {
37	      return memo;
38	    }
39	
40	    changed = true;
41	    return { ...memo, ...update };
42	  });
43	
44	  return changed ? { ...response, memos } : response;
45	}
46	
47	function patchMemoListQueryData<T>(data: T | undefined, update: MemoPatch): T | undefined {
48	  if (!data) {
49	    return data;
50	  }
51	
52	  if (isMemoListResponse(data)) {
53	    return patchMemoListResponse(data, update) as T;
54	  }
55	
56	  if (isInfiniteMemoListData(data)) {
57	    let changed = false;
58	    const pages = data.pages.map((page) => {
59	      const patchedPage = patchMemoListResponse(page, update);
60	      if (patchedPage !== page) {
61	        changed = true;
62	      }
63	      return patchedPage;
64	    });
65	
66	    return (changed ? { ...data, pages } : data) as T;
67	  }
68	
69	  return data;
70	}
71	
72	function findMemoInListResponse(response: ListMemosResponse, name: string): Memo | undefined {
73	  return response.memos.find((memo) => memo.name === name);
74	}
75	
76	function findMemoInQueryData(data: unknown, name: string): Memo | undefined {
77	  if (!data) {
78	    return undefined;
79	  }
80	
81	  if (isMemoListResponse(data)) {
82	    return findMemoInListResponse(data, name);
83	  }
84	
85	  if (isInfiniteMemoListData(data)) {
86	    for (const page of data.pages) {
87	      const memo = findMemoInListResponse(page, name);
88	      if (memo) {
89	        return memo;
90	      }
91	    }
92	  }
93	
94	  return undefined;
95	}
96	
97	function findMemoInCollectionQueries(queryClient: ReturnType<typeof useQueryClient>, name: string): Memo | undefined {
98	  for (const [, data] of queryClient.getQueriesData<unknown>({ queryKey: memoKeys.all })) {
99	    const memo = findMemoInQueryData(data, name);
100	    if (memo) {
101	      return memo;
102	    }
103	  }
104	
105	  return undefined;
106	}
107	
108	function patchMemoInCollectionQueries(queryClient: ReturnType<typeof useQueryClient>, update: MemoPatch) {
109	  queryClient.setQueriesData<MemoCollectionQueryData>({ queryKey: memoKeys.all }, (data) => patchMemoListQueryData(data, update));
110	}
111	
112	export function useMemos(request: Partial<ListMemosRequest> = {}) {
113	  return useQuery({
114	    queryKey: memoKeys.list(request),
115	    queryFn: async () => {
116	      const response = await memoServiceClient.listMemos(create(ListMemosRequestSchema, request as Record<string, unknown>));
117	      return response;
118	    },
119	  });
120	}
121	
122	export function useInfiniteMemos(request: Partial<ListMemosRequest> = {}, options?: { enabled?: boolean }) {
123	  return useInfiniteQuery({
124	    queryKey: memoKeys.list(request),
125	    queryFn: async ({ pageParam }) => {
126	      const response = await memoServiceClient.listMemos(
127	        create(ListMemosRequestSchema, {
128	          ...request,
129	          pageToken: pageParam || "",
130	        } as Record<string, unknown>),
131	      );
132	      return response;
133	    },
134	    initialPageParam: "",
135	    getNextPageParam: (lastPage) => lastPage.nextPageToken || undefined,
136	    staleTime: 1000 * 60,
137	    gcTime: 1000 * 60 * 5,
138	    enabled: options?.enabled ?? true,
139	  });
140	}
141	
142	export function useMemo(name: string, options?: { enabled?: boolean }) {
143	  return useQuery({
144	    queryKey: memoKeys.detail(name),
145	    queryFn: async () => {
146	      const memo = await memoServiceClient.getMemo({ name });
147	      return memo;
148	    },
149	    enabled: options?.enabled ?? true,
150	    staleTime: 1000 * 10, // 10 seconds - reduced to prevent stale data in collaborative editing
151	  });
152	}
153	
154	function isHTTPURL(url: string): boolean {
155	  try {
156	    const parsed = new URL(url);
157	    return parsed.protocol === "http:" || parsed.protocol === "https:";
158	  } catch {
159	    return false;
160	  }
161	}
162	
163	export function useLinkMetadata(url: string, options?: { enabled?: boolean }) {
164	  const trimmedUrl = url.trim();
165	
166	  return useQuery({
167	    queryKey: memoKeys.linkMetadata(trimmedUrl),
168	    queryFn: async () => {
169	      const metadata = await memoServiceClient.getLinkMetadata({ url: trimmedUrl });
170	      return metadata;
171	    },
172	    enabled: (options?.enabled ?? true) && isHTTPURL(trimmedUrl),
173	    staleTime: 1000 * 60 * 60 * 24,
174	    gcTime: 1000 * 60 * 60 * 24,
175	  });
176	}
177	
178	export function useCreateMemo() {
179	  const queryClient = useQueryClient();
180	
181	  return useMutation({
182	    mutationFn: async (memoToCreate: Memo) => {
183	      const memo = await memoServiceClient.createMemo({ memo: memoToCreate });
184	      return memo;
185	    },
186	    onSuccess: (newMemo) => {
187	      // Invalidate memo lists to refetch
188	      queryClient.invalidateQueries({ queryKey: memoKeys.lists() });
189	      // Add new memo to cache
190	      queryClient.setQueryData(memoKeys.detail(newMemo.name), newMemo);
191	      // Invalidate user stats
192	      queryClient.invalidateQueries({ queryKey: userKeys.stats() });
193	    },
194	  });
195	}
196	
197	export function useUpdateMemo() {
198	  const queryClient = useQueryClient();
199	
200	  return useMutation({
201	    mutationFn: async ({ update, updateMask }: { update: Partial<Memo>; updateMask: string[] }) => {
202	      const memo = await memoServiceClient.updateMemo({
203	        memo: create(MemoSchema, update as Record<string, unknown>),
204	        updateMask: create(FieldMaskSchema, { paths: updateMask }),
205	      });
206	      return memo;
207	    },
208	    onMutate: async ({ update }) => {
209	      if (!update.name) {
210	        return { previousMemo: undefined };
211	      }
212	
213	      // Cancel outgoing refetches to prevent race conditions
214	      await queryClient.cancelQueries({ queryKey: memoKeys.all });
215	
216	      // Snapshot previous value for rollback on error
217	      const previousMemo =
218	        queryClient.getQueryData<Memo>(memoKeys.detail(update.name)) || findMemoInCollectionQueries(queryClient, update.name);
219	      const memoPatch: MemoPatch = { ...update, name: update.name };
220	
221	      // Optimistically update the cache
222	      if (previousMemo) {
223	        queryClient.setQueryData(memoKeys.detail(update.name), { ...previousMemo, ...memoPatch });
224	      }
225	      patchMemoInCollectionQueries(queryClient, memoPatch);
226	
227	      return { previousMemo };
228	    },
229	    onError: (_err, { update }, context) => {
230	      // Rollback on error
231	      if (context?.previousMemo && update.name) {
232	        queryClient.setQueryData(memoKeys.detail(update.name), context.previousMemo);
233	        patchMemoInCollectionQueries(queryClient, context.previousMemo);
234	      } else {
235	        queryClient.invalidateQueries({ queryKey: memoKeys.all });
236	      }
237	    },
238	    onSuccess: (updatedMemo) => {
239	      // Update cache with server response
240	      queryClient.setQueryData(memoKeys.detail(updatedMemo.name), updatedMemo);
241	      patchMemoInCollectionQueries(queryClient, updatedMemo);
242	      // Invalidate lists to refresh
243	      queryClient.invalidateQueries({ queryKey: memoKeys.lists() });
244	      if (updatedMemo.parent) {
245	        queryClient.invalidateQueries({ queryKey: memoKeys.comments(updatedMemo.parent) });
246	      }
247	      // Invalidate user stats
248	      queryClient.invalidateQueries({ queryKey: userKeys.stats() });
249	    },
250	  });
251	}
252	
253	export function useDeleteMemo() {
254	  const queryClient = useQueryClient();
255	
256	  return useMutation({
257	    mutationFn: async (name: string) => {
258	      await memoServiceClient.deleteMemo({ name });
259	      return name;
260	    },
261	    onSuccess: (name) => {
262	      // Remove from cache
263	      queryClient.removeQueries({ queryKey: memoKeys.detail(name) });
264	      // Invalidate lists
265	      queryClient.invalidateQueries({ queryKey: memoKeys.lists() });
266	      // Invalidate user stats
267	      queryClient.invalidateQueries({ queryKey: userKeys.stats() });
268	    },
269	  });
270	}
