1	import { useUpdateMemo } from "@/hooks/useMemoQueries";
2	import type { Memo } from "@/types/proto/api/v1/memo_service_pb";
3	
4	export const useMemoActions = (memo: Memo) => {
5	  const { mutateAsync: updateMemo } = useUpdateMemo();
6	
7	  const unpinMemo = async () => {
8	    if (!memo.pinned) return;
9	    await updateMemo({ update: { name: memo.name, pinned: false }, updateMask: ["pinned"] });
10	  };
11	
12	  return { unpinMemo };
13	};
