1	import { useQueryClient } from "@tanstack/react-query";
2	import copy from "copy-to-clipboard";
3	import { useCallback } from "react";
4	import toast from "react-hot-toast";
5	import { useLocation } from "react-router-dom";
6	import { useInstance } from "@/contexts/InstanceContext";
7	import { memoKeys, useDeleteMemo, useUpdateMemo } from "@/hooks/useMemoQueries";
8	import useNavigateTo from "@/hooks/useNavigateTo";
9	import { userKeys } from "@/hooks/useUserQueries";
10	import { handleError } from "@/lib/error";
11	import { ROUTES } from "@/router/routes";
12	import { State } from "@/types/proto/api/v1/common_pb";
13	import type { Memo } from "@/types/proto/api/v1/memo_service_pb";
14	import { useTranslate } from "@/utils/i18n";
15	import { checkAllTasks, uncheckAllTasks } from "@/utils/markdown-task-actions";
16	
17	interface UseMemoActionHandlersOptions {
18	  memo: Memo;
19	  onEdit?: () => void;
20	  setDeleteDialogOpen: (open: boolean) => void;
21	}
22	
23	export const useMemoActionHandlers = ({ memo, onEdit, setDeleteDialogOpen }: UseMemoActionHandlersOptions) => {
24	  const t = useTranslate();
25	  const location = useLocation();
26	  const navigateTo = useNavigateTo();
27	  const queryClient = useQueryClient();
28	  const { profile } = useInstance();
29	  const { mutateAsync: updateMemo } = useUpdateMemo();
30	  const { mutateAsync: deleteMemo } = useDeleteMemo();
31	  const isInMemoDetailPage = location.pathname.startsWith(`/${memo.name}`);
32	
33	  const memoUpdatedCallback = useCallback(() => {
34	    // Invalidate user stats to trigger refetch
35	    queryClient.invalidateQueries({ queryKey: userKeys.stats() });
36	  }, [queryClient]);
37	
38	  const updateMemoContent = useCallback(
39	    async (nextContent: string, context: string) => {
40	      if (nextContent === memo.content) {
41	        return;
42	      }
43	
44	      try {
45	        await updateMemo({
46	          update: {
47	            name: memo.name,
48	            content: nextContent,
49	          },
50	          updateMask: ["content", "update_time"],
51	        });
52	        toast.success(t("memo.task-actions.updated"));
53	      } catch (error: unknown) {
54	        handleError(error, toast.error, {
55	          context,
56	          fallbackMessage: "An error occurred",
57	        });
58	      }
59	    },
60	    [memo.content, memo.name, t, updateMemo],
61	  );
62	
63	  const handleTogglePinMemoBtnClick = useCallback(async () => {
64	    try {
65	      await updateMemo({
66	        update: {
67	          name: memo.name,
68	          pinned: !memo.pinned,
69	        },
70	        updateMask: ["pinned"],
71	      });
72	    } catch {
73	      // do nothing
74	    }
75	  }, [memo.name, memo.pinned, updateMemo]);
76	
77	  const handleEditMemoClick = useCallback(() => {
78	    onEdit?.();
79	  }, [onEdit]);
80	
81	  const handleToggleMemoStatusClick = useCallback(async () => {
82	    const isArchiving = memo.state !== State.ARCHIVED;
83	    const state = memo.state === State.ARCHIVED ? State.NORMAL : State.ARCHIVED;
84	    const message = memo.state === State.ARCHIVED ? t("message.restored-successfully") : t("message.archived-successfully");
85	
86	    try {
87	      await updateMemo({
88	        update: {
89	          name: memo.name,
90	          state,
91	        },
92	        updateMask: ["state"],
93	      });
94	      toast.success(message);
95	    } catch (error: unknown) {
96	      handleError(error, toast.error, {
97	        context: `${isArchiving ? "Archive" : "Restore"} memo`,
98	        fallbackMessage: "An error occurred",
99	      });
100	      return;
101	    }
102	
103	    if (isInMemoDetailPage) {
104	      navigateTo(memo.state === State.ARCHIVED ? ROUTES.HOME : ROUTES.ARCHIVED);
105	    }
106	    memoUpdatedCallback();
107	  }, [memo.name, memo.state, t, isInMemoDetailPage, navigateTo, memoUpdatedCallback, updateMemo]);
108	
109	  const handleCopyLink = useCallback(() => {
110	    let host = profile.instanceUrl;
111	    if (host === "") {
112	      host = window.location.origin;
113	    }
114	    copy(`${host}/${memo.name}`);
115	    toast.success(t("message.succeed-copy-link"));
116	  }, [memo.name, t, profile.instanceUrl]);
117	
118	  const handleCopyContent = useCallback(() => {
119	    copy(memo.content);
120	    toast.success(t("message.succeed-copy-content"));
121	  }, [memo.content, t]);
122	
123	  const handleCheckAllTaskListItemsClick = useCallback(async () => {
124	    await updateMemoContent(checkAllTasks(memo.content), "Check memo task list items");
125	  }, [memo.content, updateMemoContent]);
126	
127	  const handleUncheckAllTaskListItemsClick = useCallback(async () => {
128	    await updateMemoContent(uncheckAllTasks(memo.content), "Uncheck memo task list items");
129	  }, [memo.content, updateMemoContent]);
130	
131	  const handleDeleteMemoClick = useCallback(() => {
132	    setDeleteDialogOpen(true);
133	  }, [setDeleteDialogOpen]);
134	
135	  const confirmDeleteMemo = useCallback(async () => {
136	    try {
137	      await deleteMemo(memo.name);
138	    } catch (error: unknown) {
139	      handleError(error, toast.error, { context: "Delete memo", fallbackMessage: "An error occurred" });
140	      return;
141	    }
142	    toast.success(t("message.deleted-successfully"));
143	    if (memo.parent) {
144	      queryClient.invalidateQueries({ queryKey: memoKeys.comments(memo.parent) });
145	    }
146	    if (isInMemoDetailPage) {
147	      navigateTo(ROUTES.HOME);
148	    }
149	    memoUpdatedCallback();
150	  }, [memo.name, memo.parent, t, isInMemoDetailPage, navigateTo, memoUpdatedCallback, deleteMemo, queryClient]);
151	
152	  return {
153	    handleTogglePinMemoBtnClick,
154	    handleEditMemoClick,
155	    handleToggleMemoStatusClick,
156	    handleCopyLink,
157	    handleCopyContent,
158	    handleCheckAllTaskListItemsClick,
159	    handleUncheckAllTaskListItemsClick,
160	    handleDeleteMemoClick,
161	    confirmDeleteMemo,
162	  };
163	};
